-- Please log an issue at https://github.com/pgadmin-org/pgadmin4/issues/new/choose if you find any bugs, including reproduction steps.
BEGIN;

CREATE TABLE IF NOT EXISTS public.usuario
(
    id_usuario SERIAL PRIMARY KEY,
    nome character varying(90) NOT NULL,
    email character varying(150) NOT NULL UNIQUE,
    senha TEXT NOT NULL,
    data_cadastro DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE IF NOT EXISTS public.titulo
(
    id_titulo SERIAL PRIMARY KEY,
    nome character varying(100) NOT NULL,
    genero character varying(50) NOT NULL,
    tipo character varying(20) NOT NULL,
    ano_lancamento INTEGER NOT NULL,
    sinopse TEXT,

    CONSTRAINT chk_tipo
        CHECK (tipo IN ('Filme', 'Serie')),

    CONSTRAINT chk_ano_lancamento
        CHECK (ano_lancamento >= 1888)
);

CREATE TABLE IF NOT EXISTS public.avaliacao
(
    id_avaliacao SERIAL PRIMARY KEY,
    nota INTEGER NOT NULL,
    comentario TEXT,
    data_avaliacao DATE NOT NULL DEFAULT CURRENT_DATE,
    id_titulo INTEGER NOT NULL,
    id_usuario INTEGER NOT NULL,

    CONSTRAINT chk_nota
        CHECK (nota BETWEEN 1 AND 5),

    CONSTRAINT fk_usuario
        FOREIGN KEY (id_usuario)
        REFERENCES public.usuario (id_usuario)
        ON UPDATE CASCADE
        ON DELETE CASCADE,

    CONSTRAINT fk_titulo
        FOREIGN KEY (id_titulo)
        REFERENCES public.titulo (id_titulo)
        ON UPDATE CASCADE
        ON DELETE CASCADE,

    CONSTRAINT unique_usuario_titulo
        UNIQUE (id_usuario, id_titulo)
);

END;


