SELECT
    u.nome AS usuario,
    t.nome AS titulo,
    t.tipo,
    a.nota,
    a.comentario,
    a.data_avaliacao
FROM public.avaliacao AS a
INNER JOIN public.usuario AS u
    ON a.id_usuario = u.id_usuario
INNER JOIN public.titulo AS t
    ON a.id_titulo = t.id_titulo
ORDER BY a.id_avaliacao;